create table commerce_stores(id serial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,name text not null,provider text not null check(provider in ('woocommerce','shopify')),url text not null,credentials jsonb not null,public_key text not null unique,checked_at timestamptz,last_sync_at timestamptz,error text,active boolean not null default true,unique(tenant_id,provider,url));
create table commerce_items(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,store_id int not null references commerce_stores,kind text not null check(kind in ('customers','products','orders')),external_id text not null,name text not null,status text,currency text,total numeric,email text,phone text,sku text,url text,contact_id int references contacts,detail jsonb not null default '{}',updated_at timestamptz not null default now(),unique(store_id,kind,external_id));
create table commerce_events(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,store_id int not null references commerce_stores,event_key text not null,topic text not null,at timestamptz not null default now(),unique(store_id,event_key));
do $$declare r record;begin for r in select * from(values('commerce_stores',''),('commerce_items','commerce_stores,store_id,contacts,contact_id'),('commerce_events','commerce_stores,store_id')) v(t,refs) loop execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);execute format('create policy tenant_iso on %I using(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int) with check(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int)',r.t);if r.refs<>'' then execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.refs,',')) x));end if;end loop;end $$;
create function resolve_commerce_hook(k text) returns int language sql security definer set search_path=public as $$select s.tenant_id from commerce_stores s join tenants t on t.id=s.tenant_id where s.public_key=k and s.active and t.active limit 1$$;
revoke all on function resolve_commerce_hook(text) from public;
do $$begin if exists(select 1 from pg_roles where rolname='vexora_app') then grant execute on function resolve_commerce_hook(text) to vexora_app;end if;end $$;
